const byId=new Map(authored.map(item=>[item.id,item]));
lessons.splice(0,lessons.length,...idOrder.map(id=>byId.get(id)).filter(Boolean));
groups.dl.desc='先建立神经网络直觉，再理解张量、梯度、损失、优化和泛化。';
